import pyomo.environ as pyo

DATA = {
    "products": ["advanced", "intermediate", "basic"],
    "resources": ["labor", "inspection"],
    # profit per unit (yuan)
    "profit": {
        "advanced": 300,
        "intermediate": 200,
        "basic": 100,
    },
    # resource usage per unit: usage[resource][product]
    "usage": {
        "labor": {"advanced": 17, "intermediate": 10, "basic": 2},
        "inspection": {"advanced": 8, "intermediate": 4, "basic": 2},
    },
    # available resource hours
    "availability": {
        "labor": 1000,
        "inspection": 500,
    },
    # maximum demand per product (units)
    "demand_max": {
        "advanced": 50,
        "intermediate": 80,
        "basic": 150,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # Sets
    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    # Variables: integer production quantities, bounded by demand
    model.production = pyo.Var(
        model.P,
        domain=pyo.NonNegativeIntegers,
        bounds=lambda m, p: (0, d["demand_max"][p]),
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Resource capacity constraints (one per resource)
    def capacity_rule(m, r):
        return sum(d["usage"][r][p] * m.production[p] for p in m.P) <= d["availability"][r]

    model.capacity = pyo.Constraint(model.R, rule=capacity_rule)

    return model


