import pyomo.environ as pyo

# All numeric constants from the problem live here.
DATA = {
    "products": ["advanced", "intermediate", "basic"],
    # profit per unit (yuan)
    "profit": {
        "advanced": 300,
        "intermediate": 200,
        "basic": 100,
    },
    # processing / assembly labor hours per unit
    "labor": {
        "advanced": 17,
        "intermediate": 10,
        "basic": 2,
    },
    # inspection hours per unit
    "inspect": {
        "advanced": 8,
        "intermediate": 4,
        "basic": 2,
    },
    # available capacities (hours)
    "labor_avail": 1000,
    "inspect_avail": 500,
    # maximum demand (units)
    "demand": {
        "advanced": 50,
        "intermediate": 80,
        "basic": 150,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of products
    model.P = pyo.Set(initialize=d["products"])

    # Decision variables: units produced, nonnegative integers, demand caps as upper bounds
    def bounds_rule(m, p):
        return (0, d["demand"][p])

    model.x = pyo.Var(model.P, within=pyo.NonNegativeIntegers, bounds=bounds_rule)

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Processing / assembly labor capacity: sum labor[p] * x[p] <= 1000
    def labor_rule(m):
        return sum(d["labor"][p] * m.x[p] for p in m.P) <= d["labor_avail"]

    model.labor_capacity = pyo.Constraint(rule=labor_rule)

    # Inspection hour capacity: sum inspect[p] * x[p] <= 500
    def inspect_rule(m):
        return sum(d["inspect"][p] * m.x[p] for p in m.P) <= d["inspect_avail"]

    model.inspect_capacity = pyo.Constraint(rule=inspect_rule)

    return model
